from __future__ import annotations
import numpy as np

def conj_map(basis: np.ndarray, Cmat: np.ndarray) -> np.ndarray:
    """Image of a subspace (columns = basis) under conj(x) = Cmat @ x.conj()."""
    return Cmat @ basis.conj()

def meet(A: np.ndarray, B: np.ndarray, tol: float = 1e-9) -> np.ndarray:
    """Basis of the intersection of column spaces A and B (Zassenhaus null space)."""
    if A.shape[1] == 0 or B.shape[1] == 0:
        return np.zeros((A.shape[0], 0), dtype=complex)
    M = np.hstack([A, -B])
    _, s, Vh = np.linalg.svd(M, full_matrices=True)
    smax = s[0] if s.size else 0.0
    k = M.shape[1] - int(np.sum(s > tol * max(1.0, smax)))
    if k == 0:
        return np.zeros((A.shape[0], 0), dtype=complex)
    ns = Vh.conj().T[:, M.shape[1] - k:]
    return A @ ns[:A.shape[1], :]

def reconstruct(F1: np.ndarray, F2: np.ndarray,
                Cmat: np.ndarray) -> tuple[np.ndarray, np.ndarray, np.ndarray]:
    """Recover (H20, H11, H02) from the filtration floors and conjugation."""
    H20 = F2
    CF1 = conj_map(F1, Cmat)
    H11 = meet(F1, CF1)
    H02 = conj_map(H20, Cmat)
    return H20, H11, H02

from __future__ import annotations
import numpy as np

def _rank(A: np.ndarray, tol: float = 1e-9) -> int:
    if A.size == 0:
        return 0
    s = np.linalg.svd(A, compute_uv=False)
    return int(np.sum(s > tol * max(1.0, s[0])))

def _join(*bs: np.ndarray) -> np.ndarray:
    return np.hstack(bs) if bs else np.zeros((0, 0), dtype=complex)

def _dim_meet(A: np.ndarray, B: np.ndarray) -> int:
    # dim(A cap B) = dim A + dim B - dim(A + B)
    return _rank(A) + _rank(B) - _rank(_join(A, B))

def is_hodge(H20: np.ndarray, H11: np.ndarray, H02: np.ndarray, n: int) -> bool:
    """True iff (H20, H11, H02) is a valid weight-two Hodge bigrading of C^n."""
    span_ok = _rank(_join(H20, H11, H02)) == n
    dir20 = _dim_meet(H20, _join(H11, H02)) == 0
    dir11 = _dim_meet(H11, _join(H20, H02)) == 0
    dir02 = _dim_meet(H02, _join(H20, H11)) == 0
    return bool(span_ok and dir20 and dir11 and dir02)
